import { useState } from "react";

export default function NotesForm() {
  const [note, setNote] = useState("");

  const save = () => {
    console.log(note);
  };

  const update = (event) => {
    setNote(event.target.value);
  };

  return (
    <div>
      <h6>Add Note</h6>
      <input value={note} onChange={update} />
      <button onClick={save}>Save</button>
    </div>
  );
}
